import {defaults,limits,calculate,calculateAmoebas,centres,sourceFacts} from './model.mjs';
import {mountChat,annotateSystems} from './chat.mjs';
import {reportView,systemsView,mountReports} from './reports.mjs';
import {snapshot} from './ops-model.mjs';
const $=s=>document.querySelector(s);
const state={lang:'zh',view:'assistant',scenario:'yield',p:{...defaults},applied:false,playing:false,tick:0,guide:-1,answer:null,bin:0,unit:0,exploded:false,wide:false};
const t=(zh,en)=>state.lang==='zh'?zh:en;
const n=(x,d=0)=>Number(x).toLocaleString(state.lang==='zh'?'zh-CN':'en-US',{maximumFractionDigits:d,minimumFractionDigits:d});
const money=x=>`${x<0?'−':''}¥${n(Math.abs(x))}`;
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const img=name=>`../assets/img/${name}-960.jpg`;
const badge=(type='dummy')=>`<span class="badge ${type}">${type==='dummy'?t('模拟数据','DUMMY DATA'):type==='calc'?t('测算结果','ESTIMATE'):type==='unknown'?t('待确认','UNCONFIRMED'):t('企业资料','COMPANY SOURCE')}</span>`;
const views=[['assistant','✳','AI 经营助手','AI operations assistant'],['reports','◷','定时报告与推送','Reports & delivery'],['systems','⇄','系统与数据记录','Systems & records'],['wall','▣','生产大屏','Factory display'],['overview','◫','工厂总览','Factory overview'],['orders','≡','订单与交付','Orders & delivery'],['warehouse','▦','物料与仓储','Material & warehouse'],['engineering','⌘','产品与工程','Product & engineering'],['amoeba','◉','阿米巴经营','Amoeba economics'],['scenarios','⇄','改善实验室','Scenario lab'],['sources','◇','数据与来源','Data & sources']];
const scenarios={yield:{zh:'材料利用率',en:'Material yield',image:'cap-laser-bed',desc:['同样的成品，更少的材料投入','The same output, less material input']},delivery:{zh:'交付抢救',en:'Delivery recovery',image:'forming-sparks',desc:['停机之后，比较恢复方案','Compare recovery after an interruption']},quality:{zh:'质量与版本',en:'Quality & revision',image:'qc-cmm-probe',desc:['更早发现，减少后续返工','Catch a mismatch before downstream rework']}};
const scenarioName=()=>t(scenarios[state.scenario].zh,scenarios[state.scenario].en);
const c=()=>calculate(state.p,state.scenario);
function nav(view){state.view=view;state.answer=null;history.replaceState(null,'',`#${view}`);render();window.scrollTo(0,0)}
function stat(label,value,unit,foot,cls=''){return `<div class="stat"><div class="label">${label}</div><div class="number ${cls}">${value} <span class="unit">${unit}</span></div><div class="foot">${foot}</div></div>`}
function panel(title,body,tag='',cls=''){return `<section class="panel ${cls}"><div class="panel-head"><h2>${title}</h2>${tag}</div>${body}</section>`}
function head(kicker,title,sub){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="sub">${sub}</p></div><div class="toolbar"><button data-action="guide">▷ ${t('5 分钟导览','5-minute tour')}</button><button data-action="export" class="primary">↓ ${t('导出决策简报','Export brief')}</button></div></div>`}
function strip(){return `<div class="scenario-strip"><span class="eyebrow">${t('当前情景','SCENARIO')}</span>${Object.entries(scenarios).map(([key,s])=>`<button class="scenario-button ${state.scenario===key?'active':''}" data-scenario="${key}" aria-pressed="${state.scenario===key}">${key==='yield'?'01':key==='delivery'?'02':'03'} &nbsp; ${t(s.zh,s.en)}</button>`).join('')}<span class="clock" id="clock">${clock()}</span><button class="small" data-action="play">${state.playing?'Ⅱ':'▷'} ${state.playing?t('暂停','Pause'):t('播放','Play')}</button><button class="small ghost" data-action="reset">↺ ${t('重置','Reset')}</button></div>`}
function clock(){const mins=8*60+state.tick;return `${t('模拟时钟','SIM CLOCK')} · ${String(Math.floor(mins/60)%24).padStart(2,'0')}:${String(mins%60).padStart(2,'0')} · ${t('1 秒 = 1 分钟','1s = 1m')}`}
function impact(){const m=c(),labels={material:t('材料净节省','Net material saving'),energy:t('能源节省','Energy saving'),labor:t('可避免的加班费¹','Avoidable overtime¹'),rework:t('增量返工成本节省','Incremental rework saving')};return panel(t('方案的经营影响','Proposal impact'),`<div class="panel-body"><span class="badge calc">${t('单订单 · 方案预测','PER ORDER · PROJECTED')}</span><div class="impact-total ${m.net<0?'negative':''}" data-result="net">${money(m.net)}</div><div class="desc">${t('净可避免成本 · 尚未实现','Net avoidable cost · not realized')}</div><div class="mini-bar"><i style="width:${Math.min(100,Math.max(0,m.net/Math.max(m.gross,1)*100))}%"></i></div>${Object.entries(m.components).filter(([key])=>state.scenario==='yield'?['material','energy'].includes(key):state.scenario==='delivery'?key==='labor':key==='rework').map(([key,val])=>`<div class="metric-row"><span>${labels[key]}</span><b>${money(val)}</b></div>`).join('')}<div class="metric-row"><span>${t('方案执行成本','Intervention cost')}</span><b>${money(-m.intervention)}</b></div><div class="metric-row"><span>${t('首年净收益²','Year-one net benefit²')}</span><b class="${m.yearOne>=0?'positive':'negative'}">${money(m.yearOne)}</b></div><div class="metric-row"><span>${t('静态回收期²','Simple payback²')}</span><b>${m.payback===null?'—':n(m.payback,1)+' '+t('月','mo')}</b></div><details><summary>${t('展开公式与假设','Formulas & assumptions')}</summary><p>${state.scenario==='yield'?t('(成品量 ÷ 原利用率 − 成品量 ÷ 新利用率) × (采购价 − 废料回收价) + 能源节省 − 执行成本。','(Good output / baseline yield − good output / target yield) × (purchase price − scrap recovery price) + energy saving − intervention cost.'):state.scenario==='delivery'?t('停机分钟 × 恢复比例 ÷ 60 × 可避免加班费率 − 执行成本。¹ 假设恢复时间确实减少需支付的加班。','Downtime minutes × recovery fraction / 60 × avoidable overtime rate − intervention cost. ¹ Assumes recovered time reduces paid overtime.'):t('(原返工件数 − 目标返工件数) × 每件增量返工成本 − 执行成本。','(Baseline rework units − target rework units) × incremental rework cost − intervention cost.')}</p><p>² ${t(`每年重复 ${n(state.p.ordersPerYear)} 单；一次性投入 ${money(state.p.implementation)}。首年收益 = 单订单净节省 × 年订单数 − 一次性投入。未计贴现、税费；不保证重复发生。`,`Assumes ${n(state.p.ordersPerYear)} comparable orders/year; ${money(state.p.implementation)} setup investment. Year-one benefit = per-order net saving × annual orders − setup. Excludes discounting and tax; recurrence is not guaranteed.`)}</p><p>${t('产能、订单收入和释放工时不计入上述节省，避免重复计算。','Capacity, order revenue and released staff hours are excluded to avoid double counting.')}</p></details><button class="primary wide" data-action="apply">${state.applied?'✓ '+t('方案已应用到模拟','Applied to simulation'):t('应用方案到模拟 →','Apply to simulation →')}</button><button class="wide ghost" data-nav="scenarios">${t('调整假设与比较方案','Adjust assumptions & compare')}</button></div>`, '', 'impact')}
function agent(){return panel(`<span class="agent-title"><span class="agent-avatar">✳</span><span>Hermes <span class="tiny">${t('经营助手','Operations')}</span></span></span>`,`<div class="panel-body"><div class="eyebrow">${t('脚本演示 · 无真实模型连接','SCRIPTED DEMO · NO LIVE MODEL')}</div><p>${t('从工厂信号，找到经营原因。每个回答都能追溯到当前模拟数据。','Connect factory signals to business outcomes. Every answer traces back to this scenario.')}</p><button class="prompt" data-ask="risk">↗ ${t('这张订单为什么有风险？','Why is this order at risk?')}</button><button class="prompt" data-ask="savings">↗ ${t('这笔节省是怎么算出来的？','How is the saving calculated?')}</button><button class="prompt" data-ask="brief">↗ ${t('生成今天的班组简报','Prepare the shift briefing')}</button>${state.answer?answer():''}</div>`,'','agent')}
function answer(){const m=c();let body=state.answer==='savings'?t(`当前 ${scenarioName()} 方案：毛节省 ${money(m.gross)}，扣除执行成本 ${money(m.intervention)}，净节省 ${money(m.net)} / 单。属于条件测算，尚未实现。`,`The ${scenarioName()} proposal produces ${money(m.gross)} gross savings less ${money(m.intervention)} intervention cost = ${money(m.net)} per order. Conditional estimate, not realized.`):state.answer==='brief'?t(`班组简报草稿：演示订单 DEMO-HS-260908，500 套双电机桌架。当前${state.applied?'已模拟应用改善方案':'为基线状态'}。请生产负责人核对工序计划、仓库负责人核对可用批次，再由财务验证 ${money(m.net)} 的方案收益假设。`,`Draft shift brief: DEMO-HS-260908, 500 dual-motor desk frames. ${state.applied?'Proposal applied in the simulation.':'Baseline state.'} Production reviews the route, warehouse checks usable lots, and finance validates the ${money(m.net)} benefit assumptions.`):state.scenario==='delivery'?t(`焊接停机 ${n(state.p.downtime)} 分钟。假设焊接处于关键路径且无缓冲，计划预计延后 ${n(m.lateBaseline)} 分钟；恢复方案可回收 ${n(m.recoveredMinutes)} 分钟，仍延后 ${n(m.lateTarget)} 分钟。不是已确认的交期承诺。`,`Welding is interrupted for ${n(state.p.downtime)} minutes. Assuming no schedule buffer and welding on the critical path, delay is ${n(m.lateBaseline)} minutes. The proposal recovers ${n(m.recoveredMinutes)} minutes, leaving ${n(m.lateTarget)} minutes of delay. Not a confirmed delivery promise.`):state.scenario==='quality'?t(`模拟批次 LOT-DEMO-03 使用 Rev A，而订单要求 Rev B。原方案 ${state.p.baselineRework} 件需返工；提前识别后假设为 ${state.p.targetRework} 件。隔离和返工必须由质量负责人批准。`,`Simulated lot LOT-DEMO-03 references Rev A while the order requires Rev B. Baseline rework is ${state.p.baselineRework} units; early detection assumes ${state.p.targetRework}. A quality lead must approve containment and rework.`):t(`钣金利用率为 ${state.p.baselineYield}%，生产 ${n(state.p.goodKg)} kg 成品需 ${n(m.baseInput)} kg 投料。提高至 ${state.p.targetYield}% 后需求为 ${n(m.targetInput)} kg。仓库可用库存和材料成本视图使用同一需求值。`,`Sheet-metal yield is ${state.p.baselineYield}%. ${n(state.p.goodKg)} kg good output needs ${n(m.baseInput)} kg input. At ${state.p.targetYield}% yield, input becomes ${n(m.targetInput)} kg. Warehouse requirements and costs use this same quantity.`);
return `<div class="agent-answer"><strong>${t('证据 → 解释 → 人工决策','Evidence → explanation → human decision')}</strong><p>${body}</p><div class="evidence-links"><button data-nav="orders">MES / ERP ↗</button><button data-nav="warehouse">WMS ↗</button><button data-nav="scenarios">${t('公式','Formulas')} ↗</button></div></div>`}
function right(){return `<aside class="stack impact-sticky">${impact()}${agent()}</aside>`}
function factoryMap(){const focus=state.scenario==='yield'?'sheet':state.scenario==='delivery'?'weld':'inspect';return `<div class="map-area ${state.playing?'':'paused'}"><svg class="factory-svg" viewBox="0 0 1070 490" role="img" aria-label="${t('七个工艺中心的交互式示意图','Interactive schematic of seven process centres')}"><defs><pattern id="hatch" width="13" height="13" patternUnits="userSpaceOnUse"><path d="M0 13L13 0" stroke="#9cb5ab" stroke-opacity=".15"/></pattern></defs><path d="M160 220H890V450H160Z" fill="none" stroke="#354c48" stroke-width="28" opacity=".25"/><path class="route active" d="M435 195H680V245H190V370H925"/><path class="route" d="M190 195H435M190 195V365"/><text x="820" y="100" fill="#728983" font-size="11" letter-spacing="3">HERSTAR / SUZHOU</text><text x="820" y="123" fill="#a6e8bd" font-size="13">${t('七大工艺 · 一条数据链','7 PROCESSES · ONE DATA THREAD')}</text><text x="820" y="145" fill="#728983" font-size="10">${t('示意布局 · 非真实平面图','SCHEMATIC · NOT AN ACTUAL FLOOR PLAN')}</text>${centres.map((a,i)=>{const highlight=a.id===focus;const color=highlight&&!state.applied?'#f7c66b':'#a6e8bd';return `<g class="node" role="button" tabindex="0" data-centre="${a.id}" aria-label="${t(a.zh,a.en)}" transform="translate(${a.x},${a.y})"><rect class="node-floor" x="-15" y="15" width="195" height="143" rx="8"/><path class="node-side" d="M10 45L42 20V105L10 130Z"/><path class="node-front" d="M10 70L142 70V130H10Z"/><path class="node-roof" d="M10 45L42 20H170L142 70H10Z"/><path d="M10 45L42 20H170L142 70H10Z" fill="url(#hatch)"/><path class="node-side" d="M142 70L170 20V100L142 130Z"/><rect x="27" y="88" width="18" height="24" fill="#0e2024"/><rect x="53" y="88" width="18" height="24" fill="#0e2024"/><rect x="82" y="87" width="43" height="43" fill="#142a2c"/><path d="M85 97H121M85 105H121M85 113H121" stroke="#496461"/><rect x="35" y="38" width="75" height="8" rx="2" fill="${color}" opacity=".7"/><circle cx="158" cy="144" r="4" fill="${color}"/><text x="0" y="180" font-size="15" fill="#e0ebe6">${String(i+1).padStart(2,'0')} ${t(a.zh,a.en)}</text><text x="0" y="199" font-size="10" fill="${highlight?color:'#79928b'}">${a.code} · ${highlight?(state.applied?t('方案模拟','PROPOSAL'):t('需要关注','ATTENTION')):t('模拟运行','SIM RUNNING')}</text></g>`}).join('')}</svg><div class="map-legend"><span><i class="legend-dot"></i>${t('模拟运行','Simulated running')}</span><span><i class="legend-dot amber"></i>${t('当前情景关注点','Scenario focus')}</span><span>${t('点击工艺中心查看数据 →','Select a centre to inspect →')}</span>${badge('source')}</div></div>`}
function orderTable(){const m=c(),delay=state.applied?m.lateTarget:m.lateBaseline;return `<div class="table-wrap"><table><thead><tr><th>${t('演示订单','DEMO ORDER')}</th><th>${t('产品 / 数量','PRODUCT / QTY')}</th><th>${t('状态','STATUS')}</th><th>${t('预计延迟','MODELLED DELAY')}</th></tr></thead><tbody><tr><td><button class="link-button" data-nav="orders">DEMO-HS-260908 ↗</button></td><td>${t('双电机桌架 · 500 套','Dual-motor frame · 500 sets')}</td><td><span class="badge ${state.applied?'':'dummy'}">${state.applied?t('方案模拟','PROPOSAL'):t('基线','BASELINE')}</span></td><td class="warning">+${n(delay)} min</td></tr></tbody></table></div>`}
function sparkline(){return `<svg class="sparkline" viewBox="0 0 500 100" preserveAspectRatio="none" aria-label="${t('固定虚构能耗趋势','Fixed fictional energy trace')}"><path d="M0 25H500M0 65H500" stroke="#ffffff0b"/><path d="M0 80L25 65L50 68L75 40L100 51L125 43L150 65L175 32L200 38L225 49L250 28L275 37L300 23L325 46L350 32L375 42L400 18L425 30L450 25L475 36L500 22" fill="none" stroke="#a6e8bd" stroke-width="2"/><path d="M0 80L25 65L50 68L75 40L100 51L125 43L150 65L175 32L200 38L225 49L250 28L275 37L300 23L325 46L350 32L375 42L400 18L425 30L450 25L475 36L500 22V100H0Z" fill="#a6e8bd0c"/></svg>`}
function overview(){const m=c(),yieldNow=state.applied&&state.scenario==='yield'?state.p.targetYield:state.p.baselineYield;return head('OPERATIONS / 01',t('工厂运营总览','Factory operations'),t('以恒升制造能力为背景，连接一张订单、一条产线与一笔经营账。','One order, a connected production flow, and transparent economics—grounded in Herstar’s manufacturing context.'))+strip()+`<div class="stats">${stat(t('当前追踪订单','Tracked demo order'),'500',t('套','sets'),'DEMO-HS-260908 · '+t('模拟数据','DUMMY DATA'))}${stat(t('材料利用率','Material yield'),n(yieldNow,1),'%',t('模拟输入 · 可在实验室修改','Dummy input · editable in Scenario lab'),'positive')}${stat(t('预计订单延迟','Modelled order delay'),n(state.applied?m.lateTarget:m.lateBaseline),'min',t('关键路径假设 · 测算结果','Critical-path assumption · ESTIMATE'),'warning')}${stat(t('方案净可避免成本','Net avoidable cost'),money(m.net),'',t('单订单测算 · 非实际收益','Per-order estimate · not realized'),'positive')}</div><div class="grid-main"><div><section class="panel"><div class="panel-head"><div><h2>${t('制造全景','Manufacturing landscape')}</h2><div class="eyebrow">${t('数据流演示 / 非真实系统连接','DATA FLOW DEMO / NO LIVE CONNECTIONS')}</div></div>${badge('dummy')}</div>${factoryMap()}<div class="alert-line"><strong>↗ ${scenarioName()}</strong><span>${t(scenarios[state.scenario].desc[0],scenarios[state.scenario].desc[1])}</span><button class="small" data-nav="scenarios">${t('比较方案','Compare')}</button></div><div class="connector-row">${[['SAP ERP','orders'],['MES','orders'],['WMS','warehouse'],['PLM','engineering']].map(([name,view])=>`<button class="connector" data-nav="${view}"><strong><i class="dot"></i>${name}</strong><span>${t('模拟适配器 · 点击追溯','SIM ADAPTER · INSPECT')}</span></button>`).join('')}</div></section><div class="bottom-grid">${panel(t('从订单开始追溯','Start with the order'),orderTable(),badge())}${panel(t('设备信号预览','Equipment signal preview'),`<div class="panel-body">${sparkline()}<div class="chart-labels"><span>${t('固定模拟样本','FIXED DUMMY SAMPLE')}</span><button class="link-button" data-centre="sheet">${t('查看遥测 →','Inspect telemetry →')}</button></div></div>`,badge())}</div></div>${right()}</div>`}
function orders(){const m=c();return head('ERP + MES / 02',t('订单与生产进度','Orders and production progress'),t('所有订单、价格、路线及时间为虚构演示值；生产系统保持人工决策。','All orders, prices, routes and times are fictional. Production decisions remain with authorized staff.'))+strip()+`<div class="grid-main"><div class="stack">${panel('DEMO-HS-260908',`<div class="panel-body"><div class="stats">${stat(t('产品','Product'),t('双电机','Dual-motor'),'',t('桌架 · 企业产品类别','Desk frame · company product category'))}${stat(t('订单数量','Order quantity'),'500',t('套','sets'),t('模拟数据','DUMMY DATA'))}${stat(t('模拟单价','Dummy unit price'),'¥800','',t('非正式报价','Not a quotation'))}${stat(t('模拟订单收入','Dummy order revenue'),'¥400,000','',t('不计入节省','Excluded from savings'))}</div><div class="callout">${t('演示客户：Example Office（虚构）。订单要求 Rev B，关联批次 LOT-DEMO-03。承诺时点为模拟日 D+3 17:00，路线、标准工时和关键路径均为假设。','Fictional customer: Example Office. Required revision: B; linked lot: LOT-DEMO-03. Due at simulation day D+3 17:00. Routing, standard hours and critical path are assumptions.')}</div></div>`,badge())}${panel(t('生产时间线 · 基线 vs 方案','Production timeline · baseline vs proposal'),`<div class="timeline">${[t('钣金 / 冲压','Sheet / stamp'),t('焊接','Welding'),t('喷涂','Coating'),t('组装','Assembly'),t('检测 / 包装','QC / pack')].map((label,i)=>`<div class="timeline-row"><span>${label}</span><div class="timeline-rail"><div class="timeline-block ${i===1?'delayed':''}" style="left:${i*14}%;width:${18+(i===1?Math.min(14,m.lateBaseline/20):0)}%"></div>${state.applied&&i===1?`<div class="timeline-block improved" style="left:${i*14}%;width:${18+Math.min(14,m.lateTarget/20)}%;height:6px;top:22px"></div>`:''}</div><span>${i===1?'+'+n(state.applied?m.lateTarget:m.lateBaseline)+'m':'D+'+Math.min(3,i)}</span></div>`).join('')}</div><div class="timeline-key">${t('长度示意，不是排程求解器。绿线表示应用后的方案。','Illustrative lengths, not a scheduling solver. Green overlay shows the applied proposal.')}</div>`,badge())}${panel(t('交期影响','Delivery impact'),`<div class="panel-body"><div class="compare"><div>${t('基线：预计延迟','Baseline: expected delay')}<b class="warning">${n(m.lateBaseline)} min</b></div><div>${t('方案：预计延迟','Proposal: expected delay')}<b class="positive">${n(m.lateTarget)} min</b></div></div><p class="footnote">${state.scenario==='yield'?t('本材料情景仅改变用料和能耗，交期未设改善；保留独立的 60 分钟模拟缓冲缺口。','The material scenario changes input and energy only. Timing keeps an independent 60-minute simulated buffer gap.'):t('简化模型：延误直接传递至交付；不含排班、搬运和后续工序缓冲。','Simplified propagation to delivery; excludes calendars, handling and downstream buffers.')}</p><button data-ask="risk">✳ ${t('让 Hermes 解释交付风险','Ask Hermes about delivery risk')}</button></div>`,badge('calc'))}</div>${right()}</div>`}
function warehouse(){const m=c(),input=state.applied&&state.scenario==='yield'?m.targetInput:m.baseInput,available=10800,short=Math.max(0,input-available);return head('WMS + MATERIAL / 03',t('库存与材料需求','Inventory and material requirements'),t('一份可用库存与投料需求，贯穿仓库、生产和成本测算。','One material requirement shared across warehouse, production and cost calculations.'))+strip()+`<div class="grid-main"><div class="stack">${panel(t('仓位与批次','Bins & lots'),`<div class="panel-body"><div class="stats">${stat(t('可用钢材','Usable steel'),n(available),'kg',t('模拟库存','DUMMY STOCK'))}${stat(t('当前投料需求','Current input requirement'),n(input),'kg',t('来自材料模型','From the material model'))}${stat(t('缺口','Shortfall'),n(short),'kg',t('待采购或重新分配','Purchase or reallocate'),short?'warning':'positive')}${stat(t('隔离库存','Quality-held stock'),'600','kg',t('不计入可用库存','Excluded from usable stock'),'warning')}</div><div class="warehouse-grid">${Array.from({length:15},(_,i)=>`<button class="bin ${i===2?'hold':i>11?'empty':''} ${state.bin===i?'selected':''}" data-bin="${i}"><span>${String.fromCharCode(65+Math.floor(i/5))}-${String(i%5+1).padStart(2,'0')}</span><b>${i===2?'600 kg':i>11?'—':n(i===0?1800:900)+' kg'}</b><span>${i===2?t('质量隔离','ON HOLD'):i>11?t('空位','EMPTY'):t('可用','AVAILABLE')}</span></button>`).join('')}</div><div class="callout" id="bin-detail">${binDetail()}</div><p class="footnote">${t('十个仓位各 900 kg，加 A-01 的 1,800 kg = 10,800 kg 可用。A-03 隔离 600 kg；其余三仓为空。仓位布局、批次和重量全部虚构。','Ten bins at 900 kg plus A-01 at 1,800 kg = 10,800 kg usable. A-03 holds 600 kg; three bins are empty. Layout, lots and weights are fictional.')}</p></div>`,badge())}${panel(t('材料流 · 固定成品产出','Material flow · fixed good output'),`<div class="panel-body"><div class="flow-diagram"><div class="flow-block"><span>${t('投入','INPUT')}</span><b>${n(input)}</b><span>kg</span></div><span class="flow-arrow">→</span><div class="flow-block"><span>${t('合格成品','GOOD OUTPUT')}</span><b>${n(state.p.goodKg)}</b><span>kg</span></div><span class="flow-arrow">+</span><div class="flow-block loss"><span>${t('废料','SCRAP')}</span><b>${n(input-state.p.goodKg)}</b><span>kg</span></div></div><p class="footnote">${t('废料按回收价抵减材料成本；不把减少采购与减少废料重复相加。成品公斤数为本模拟订单的假设等效金属重量。','Scrap recovery credits reduce material cost; avoided input and avoided scrap are not added twice. Good-output kg is assumed equivalent metal weight for this demo order.')}</p><button data-nav="scenarios">${t('调整材料利用率 →','Adjust material yield →')}</button></div>`,badge('calc'))}</div>${right()}</div>`}
function binDetail(){const i=state.bin;return `<b>${t('所选仓位','Selected bin')} ${String.fromCharCode(65+Math.floor(i/5))}-${String(i%5+1).padStart(2,'0')}</b> · ${i===2?'LOT-DEMO-03':i>11?t('暂无批次','No lot'):'LOT-DEMO-'+String(i+1).padStart(2,'0')}<br>${i===2?t('质量隔离 · Rev A / Rev B 版本情景的关联批次；任何方案均不自动解除隔离。','Quality held · linked to the Rev A / Rev B scenario; proposals never automatically release the hold.'):i>11?t('空仓位 · 无可用库存','Empty bin · no usable stock'):t('模拟钢材 · 可用；材料牌号和炉号待真实系统接入。','Dummy steel · usable; actual grades and heat numbers require source-system integration.')}`}
function columnSVG(){return `<svg class="assembly-svg" viewBox="0 0 650 320" role="img" aria-label="${t('升降立柱结构示意，非生产 CAD','Illustrative lifting column, not production CAD')}"><defs><linearGradient id="steel"><stop stop-color="#485a60"/><stop offset=".5" stop-color="#b6c2c5"/><stop offset=".7" stop-color="#52676e"/><stop offset="1" stop-color="#7b8c92"/></linearGradient></defs><g transform="translate(255,30)"><g class="explode" style="transform:translate(${state.exploded?-100:0}px,0)"><path d="M0 70L60 55L106 70L46 86Z" fill="#bdc7ca"/><path d="M0 70V240L46 260V86Z" fill="url(#steel)"/><path d="M46 86L106 70V240L46 260Z" fill="#3b5058"/><path d="M7 240L-50 262L8 282L148 247L110 234" fill="#657e85"/></g><g class="explode" style="transform:translate(${state.exploded?30:0}px,${state.exploded?-20:0}px)"><path d="M18 25L65 13L91 24L46 38Z" fill="#becace"/><path d="M18 25V164L46 177V38Z" fill="url(#steel)"/><path d="M46 38L91 24V163L46 177Z" fill="#657a83"/></g><g class="explode" style="transform:translate(${state.exploded?145:0}px,0)"><path d="M34 0V113L52 120V5Z" fill="#adbec0"/><path d="M52 5L77 0V112L52 120Z" fill="#71858a"/><path d="M18 0L80 -15L110 -2L50 13Z" fill="#94a9ae"/></g></g><path d="M115 175H220M420 100H520M420 240H520" stroke="#a6e8bd" stroke-dasharray="3 4"/><text x="65" y="165" fill="#a6e8bd" font-size="11">${t('外管','OUTER TUBE')}</text><text x="480" y="90" fill="#a6e8bd" font-size="11">${t('伸缩结构','TELESCOPIC')}</text><text x="480" y="230" fill="#a6e8bd" font-size="11">${t('底座','BASE')}</text><text x="20" y="300" fill="#9aabad" font-size="10">${t('示意几何 · 非真实 CAD / 尺寸','ILLUSTRATIVE GEOMETRY · NOT PRODUCTION CAD / DIMENSIONS')}</text></svg>`}
function engineering(){return head('PLM + QUALITY / 04',t('工程版本与批次追溯','Engineering revisions and batch traceability'),t('真实产品类别与示意结构，结合虚构的版本事件演示追溯与人工复核。','A real product category and illustrative structure, with a fictional revision event for traceability and review.'))+strip()+`<div class="grid-main"><div class="stack">${panel(t('升降立柱 · 结构探索','Lifting column · structure explorer'),`${columnSVG()}<div class="panel-body"><button data-action="explode">${state.exploded?t('收起结构','Assemble'):t('展开结构','Explode assembly')}</button><p class="footnote">${t('产品类别取自企业目录；本几何、BOM 和版本差异均为示意，不能作为制造依据。','Product category is sourced from the company catalogue. Geometry, BOM and revision differences are illustrative, not manufacturing instructions.')}</p></div>`,badge('source'))}${panel(t('版本差异 / Rev A → Rev B','Revision comparison / Rev A → Rev B'),`<div class="revision-row"><b>${t('图纸状态','Drawing')}</b><span>Rev A: ${t('模拟旧版','dummy old revision')} → Rev B: ${t('订单要求版','order-required revision')}</span></div><div class="revision-row"><b>${t('变更项','Change')}</b><span>${t('示意安装孔位变更；无真实尺寸或工艺参数。','Illustrative mounting-hole change; no actual dimensions or process parameters.')}</span></div><div class="revision-row"><b>${t('关联对象','Affected')}</b><span>DEMO-HS-260908 · LOT-DEMO-03 · WD-03</span></div><div class="revision-row"><b>${t('质量处理','Disposition')}</b><span>${state.applied&&state.scenario==='quality'?t('模拟：提前识别，待质量负责人批准返工','Simulated: detected early, rework pending quality approval'):t('模拟：发现不一致，批次保持隔离','Simulated: mismatch detected; lot remains on hold')}</span></div><div class="panel-body"><button data-scenario="quality">${t('进入版本异常情景 →','Open revision scenario →')}</button><button data-nav="warehouse">${t('追溯库存批次','Trace warehouse lot')}</button></div>`,badge())}${panel(t('示意 BOM','Illustrative BOM'),`<div class="table-wrap"><table><thead><tr><th>${t('部件','COMPONENT')}</th><th>${t('数量 / 套','QTY / SET')}</th><th>${t('数据性质','PROVENANCE')}</th></tr></thead><tbody>${[[t('升降立柱','Lifting column'),2],[t('驱动电机','Drive motor'),2],[t('横梁','Crossbeam'),1],[t('控制器','Controller'),1]].map(([label,qty])=>`<tr><td>${label}</td><td>${qty}</td><td>${badge()}</td></tr>`).join('')}</tbody></table></div>`,badge())}</div>${right()}</div>`}
const controlNames={goodKg:['合格成品量 · kg','Good output · kg'],materialPrice:['材料采购价 · ¥/kg','Material price · ¥/kg'],scrapPrice:['废料回收价 · ¥/kg','Scrap recovery · ¥/kg'],baselineYield:['基线材料利用率 · %','Baseline yield · %'],targetYield:['目标材料利用率 · %','Target yield · %'],downtime:['焊接停机 · 分钟','Welding downtime · min'],recovery:['可恢复比例 · %','Recoverable fraction · %'],cycle:['单位节拍 · 分钟/套','Cycle time · min/set'],overtimeRate:['可避免加班费 · ¥/小时','Avoidable overtime · ¥/hr'],deliveryCost:['恢复方案执行费 · ¥','Recovery intervention · ¥'],baselineRework:['基线返工件数','Baseline rework units'],targetRework:['提前识别后返工件数','Rework after early detection'],reworkCost:['增量返工成本 · ¥/件','Incremental rework cost · ¥/unit'],qualityCost:['检查执行费 · ¥','Inspection intervention · ¥'],baseEnergy:['基线能耗 · kWh','Baseline energy · kWh'],targetEnergy:['目标能耗 · kWh','Target energy · kWh'],tariff:['电价 · ¥/kWh','Energy tariff · ¥/kWh'],yieldCost:['排样方案执行费 · ¥','Nesting intervention · ¥'],implementation:['一次性项目投入 · ¥','One-time investment · ¥'],ordersPerYear:['每年可重复订单数','Comparable orders / year'],reports:['每月报表数量','Reports per month'],minutesSaved:['每份报表节省 · 分钟','Minutes released per report']};
function control(key){const [min,max,step]=limits[key];return `<div class="control"><label for="p-${key}">${t(...controlNames[key])}<output id="out-${key}">${n(state.p[key],step<1?1:0)}</output></label><input id="p-${key}" type="range" min="${min}" max="${max}" step="${step}" value="${state.p[key]}" data-param="${key}"><div class="range-ends"><span>${n(min,step<1?1:0)}</span><span>${n(max,step<1?1:0)}</span></div></div>`}
function scenarioControls(){const keys=state.scenario==='yield'?['goodKg','baselineYield','targetYield','materialPrice','scrapPrice','baseEnergy','targetEnergy','tariff','yieldCost']:state.scenario==='delivery'?['downtime','recovery','cycle','overtimeRate','deliveryCost']:['baselineRework','targetRework','reworkCost','qualityCost'];return panel(t('修改假设，立即看见影响','Change an assumption. See the impact.'),`<div class="panel-body"><div class="controls">${keys.map(control).join('')}</div><p class="footnote">${t('所有滑杆值都是模拟假设。允许目标比基线更差，结果会显示负收益。滑动后之前的“已应用”状态会清除，需再次应用。','All sliders are dummy assumptions. Worse targets are allowed and produce negative benefits. Editing clears the applied state; apply again to update the operational views.')}</p></div>`,badge())}
function compareResult(){const m=c(),before=state.scenario==='yield'?m.baseInput:state.scenario==='delivery'?m.lateBaseline:state.p.baselineRework,after=state.scenario==='yield'?m.targetInput:state.scenario==='delivery'?m.lateTarget:state.p.targetRework,unit=state.scenario==='yield'?'kg':state.scenario==='delivery'?'min':t('件','units');return `<div class="compare"><div>${t('基线','BASELINE')}<b class="warning">${n(before)} ${unit}</b><small>${state.scenario==='yield'?t('投料需求','Input required'):state.scenario==='delivery'?t('订单延迟','Order delay'):t('返工数量','Rework quantity')}</small></div><div>${t('改善方案','PROPOSAL')}<b class="positive">${n(after)} ${unit}</b><small>${t('条件测算 · 非实际结果','Conditional estimate · not actual')}</small></div></div>${state.scenario==='delivery'?`<div class="callout" style="margin-top:15px">${t(`回收 ${n(m.recoveredMinutes)} 分钟，可释放约 ${n(m.capacity)} 套加工能力。未计为收入或利润；需有订单需求及后续产能。`,`Recover ${n(m.recoveredMinutes)} minutes, equivalent to approximately ${n(m.capacity)} sets of capacity. Not counted as revenue or profit; requires demand and downstream capacity.`)}</div>`:''}<div class="waterfall">${[[t('毛节省','Gross saving'),m.gross,''],[t('执行成本','Intervention'),-m.intervention,'cost'],[t('净节省','Net saving'),m.net,'total']].map(([name,value,cls])=>`<div class="waterfall-item"><b>${money(value)}</b><div class="waterfall-bar ${cls}" style="height:${Math.max(3,Math.abs(value)/Math.max(Math.abs(m.gross),Math.abs(m.intervention),Math.abs(m.net),1)*135)}px;${value<0?'background:var(--red)':''}"></div><span>${name}</span></div>`).join('')}</div><p class="footnote">${t('组成对比图；正负号表示收益与支出，不代表累计现金流。每次只估算当前情景，不叠加三个案例。','Component comparison; signs indicate benefits and costs, not accumulated cash flow. Only the active scenario is counted; the three cases are not stacked.')}</p>`}
function scenarioLab(){return head('WHAT-IF LAB / 06',t('改善方案成本测算','Improvement cost estimates'),t('拖动假设，看材料、交期和经营结果同步变化。每个数值都有计算依据。','Adjust the assumptions and watch material, delivery and economics respond. Every result has a visible calculation.'))+strip()+`<div class="scenario-cards">${Object.entries(scenarios).map(([key,s],i)=>`<button class="scenario-card ${key===state.scenario?'selected':''}" data-scenario="${key}"><img src="${img(s.image)}" alt=""><div class="inner"><span class="eyebrow">0${i+1} / ${t('模拟情景','DUMMY SCENARIO')}</span><h3>${t(s.zh,s.en)}</h3><p>${t(...s.desc)}</p></div></button>`).join('')}</div><div class="grid-main"><div class="stack">${scenarioControls()}${panel(t('从基线，到可比较的方案','From baseline to a comparable proposal'),`<div class="panel-body" id="comparison">${compareResult()}</div>`,badge('calc'))}${panel(t('投入、重复频次与报表工时','Investment, recurrence & reporting hours'),`<div class="panel-body"><div class="controls">${['implementation','ordersPerYear','reports','minutesSaved'].map(control).join('')}</div><div id="time-result" class="callout" style="margin-top:20px">${timeResult()}</div></div>`,badge())}</div>${right()}</div>`}
function timeResult(){return t(`独立报表假设：每月可释放 ${n(c().reportHours,1)} 小时。属于可重新分配的人员时间，不计入现金节省，也不假设裁员。`,`Separate reporting assumption: ${n(c().reportHours,1)} staff hours released per month. Reallocatable time, excluded from cash savings; no headcount reduction assumed.`)}
function amoebaData(){return calculateAmoebas(state.p,state.scenario,state.applied)}
function amoeba(){const units=amoebaData(),u=units[state.unit],m=c(),external=units.reduce((sum,x)=>sum+x.external,0),net=400000-external+(state.applied?m.net:0);return head('AMOEBA ECONOMICS / 05',t('经营单元核算','Operating unit accounts'),t('示意管理核算：内部转移、外部费用、工时与改善收益。不是恒升实际财务账。','Illustrative management accounting: internal transfers, external expenses, hours and improvements. Not Herstar’s actual accounts.'))+strip()+`<div class="grid-main"><div class="stack">${panel(t('经营单元 · 单订单核算','Operating units · per-order model'),`<div class="panel-body"><div class="amoeba-units">${units.map((x,i)=>`<button class="amoeba-unit ${state.unit===i?'active':''}" data-unit="${i}"><h3>${t(x.zh,x.en)}</h3><strong>${n((x.revenue-x.current)/x.hours,1)}</strong><span>${t('¥ / 小时 · 单位时间附加值','¥ / hour · added value per hour')}</span></button>`).join('')}</div><p class="footnote">${t('三个示意单元，不代表恒升已采用此组织形式。工时固定；本例费用排除基础人工费用，包含情景中的可避免加班或增量返工费用。需财务定义后才能用于实际考核。','Three illustrative units, not an assertion about Herstar’s organization. Hours are fixed. Expenses exclude base labor and include scenario overtime or incremental rework costs. Finance must approve definitions before real performance use.')}</p></div>`,badge())}${panel(t(u.zh,u.en)+t(' · 经营明细',' · operating detail'),`<div class="panel-body"><div class="metric-row"><span>${state.unit===2?t('外部客户收入','External customer revenue'):t('内部转移收入','Internal transfer revenue')}</span><b>${money(u.revenue)}</b></div><div class="metric-row"><span>${t('基线费用','Baseline expenses')}</span><b>${money(u.expense)}</b></div><div class="metric-row"><span>${t('方案费用','Proposed expenses')}</span><b>${money(u.proposal)}</b></div><div class="metric-row"><span>${t('总工作时间','Total hours')}</span><b>${u.hours} h</b></div><div class="compare" style="margin-top:18px"><div>${t('基线附加值 / 小时','Baseline added value / hour')}<b>${money((u.revenue-u.expense)/u.hours)}</b></div><div>${t('方案附加值 / 小时','Proposed added value / hour')}<b>${money((u.revenue-u.proposal)/u.hours)}</b></div></div><p class="footnote">${t('公式 =（该单元收入 − 定义内费用）÷ 总工时。只把当前情景净收益分配到对应单元一次，投入单独在回收期模型处理。','Formula = (unit revenue − defined expenses) / total hours. Current-scenario net benefit is allocated once to its affected unit. Setup investment is handled separately in payback.')}</p></div>`,badge('calc'))}${panel(t('合并视图 · 消除内部交易','Consolidated view · eliminate internal transfers'),`<div class="panel-body"><div class="metric-row"><span>${t('内部转移抵消','Internal transfers eliminated')}</span><b>¥225,000</b></div><div class="metric-row"><span>${t('对外收入','External revenue')}</span><b>¥400,000</b></div><div class="metric-row"><span>${t('外部定义内费用','External defined expenses')}</span><b>${money(external-(state.applied?m.net:0))}</b></div><div class="metric-row"><span>${t('合并附加值（非净利润）','Consolidated added value (not net profit)')}</span><b class="positive">${money(net)}</b></div><div class="callout" style="margin-top:16px">${t('不把内部转移收入计为集团新增收入。此附加值尚未扣除基础人工、折旧和全部管理费用，不是净利润。还需同时考核交期、质量与在制品。','Internal transfer revenue is not additional company revenue. This added value excludes base labor, depreciation and full overhead; it is not net profit. Pair it with delivery, quality and WIP measures.')}</div></div>`,badge('calc'))}</div>${right()}</div>`}
function sources(){return head('PROVENANCE / 07',t('数据来源与计算口径','Sources and calculation definitions'),t('企业资料、模拟数据、测算结果和待确认信息分别标注，并随导出保留。','Company sources, dummy inputs, estimates and unconfirmed information remain labelled, including in exports.'))+`<div class="section-grid"><div class="stack">${panel(t('数据来源登记','Source register'),`<div class="panel-body source-list">${sourceFacts.map(f=>`<div class="source-item"><div>${t(f.zh,f.en)}<p>${f.status==='public'?t('本次已查看企业公开目录。','Company public catalogue inspected for this demo.'):f.status==='repo'?t('来自本地 README 的既有企业资料；本次未独立验证现时准确性。','From existing company-source notes in the local README; current accuracy not independently reverified.'):f.status==='unknown'?t('没有凭据或系统访问；所有连接状态均为模拟。','No credentials or system access; all connection states are simulated.'):t('专为演示构造，不可用于真实生产或经营决策。','Created for demonstration; not suitable for actual production or business decisions.')}</p>${f.source?`<a href="${f.source}" target="_blank" rel="noopener">${t('查看来源','View source')} ↗</a>`:''}</div>${badge(f.status==='dummy'?'dummy':f.status==='unknown'?'unknown':'source')}</div>`).join('')}</div>`,badge('source'))}</div><div class="stack">${panel(t('连接方式示意','Integration concept'),`<div class="system-flow"><div>SAP · MES · WMS · PLM<small>${t('演示适配器','Demo adapters')}</small></div><span>↓</span><div>${t('共享数据与计算模型','Shared data & calculation model')}</div><span>↓</span><div>MCP → Hermes<small>${t('带证据的解释与决策草稿','Evidence-linked explanations & decision drafts')}</small></div></div><div class="panel-body"><div class="callout">${t('此应用没有真实 SAP / MES / WMS / PLM / 设备 / LLM 连接，不发送消息、不写入生产系统。图中的连接表示未来的集成位置。','This app has no live SAP, MES, WMS, PLM, equipment or LLM connection. It sends no messages and writes to no production system. Connections illustrate future integration points.')}</div></div>`,badge())}${panel(t('计算口径与边界','Calculation definitions'),`<div class="panel-body"><p>${t('期间：每张模型订单。币种：人民币。年度情景：订单数 × 单订单净收益 − 一次性投入。','Period: one modelled order. Currency: CNY. Annual scenario: order count × per-order net benefit − setup investment.')}</p><p>${t('没有实际节省累计计数器。动画和时钟只驱动演示信号，财务结果只随明确假设变化。','There is no realized-savings counter. Animation and the clock drive demonstration signals; financial results change only with explicit assumptions.')}</p><p>${t('三个案例互斥；不把时间释放、产能、收入和成本节省相加。对更差的方案显示负收益。','Scenarios are mutually exclusive. Released time, capacity, revenue and cost savings are not added together. Worse proposals show negative benefit.')}</p><p>${t('项目不保存真实客户数据。输入仅在当前页面内存中；刷新回到默认状态。可导出带假设和来源的 HTML / JSON。','No real customer data is stored. Inputs live only in page memory; refresh restores defaults. Export labelled assumptions and sources as HTML / JSON.')}</p><button data-action="json">↓ ${t('导出完整情景 JSON','Export complete scenario JSON')}</button></div>`,badge('calc'))}</div></div>`}
const tour=[['overview','认识恒升制造全景','Explore Herstar manufacturing','点击钣金中心，看模拟设备数据。然后继续追踪同一订单。','Select Sheet metal to inspect dummy equipment data, then follow the same order.'],['orders','追踪一张订单','Follow one order','ERP 承诺与 MES 工序共享同一订单；比较基线和方案延迟。','ERP commitment and MES operations share one order. Compare baseline and proposed delay.'],['warehouse','看物料与损耗','Inspect material and loss','查看 A-03 隔离批次。可用库存不包含隔离材料。','Inspect held lot A-03. Usable stock excludes held material.'],['engineering','工程版本与质量','Engineering revision and quality','展开立柱结构，查看 Rev A / Rev B 虚构版本事件。','Explode the column and inspect the fictional Rev A / Rev B event.'],['scenarios','亲手计算改善收益','Calculate the improvement','拖动目标利用率，查看净节省；点击“应用方案到模拟”。','Move target yield, inspect net savings, then apply the proposal to the simulation.'],['amoeba','把改善带入经营账','Bring the improvement into unit economics','查看附加值与内部交易抵消，再导出决策简报带走。','Review added value and eliminated internal transfers, then export a decision brief.']];
function guide(){if(state.guide<0)return '';const step=tour[state.guide];return `<div class="guide" role="region" aria-label="${t('演示导览','Guided tour')}"><div class="count">0${state.guide+1}</div><div><strong>${t(step[1],step[2])}</strong><p>${t(step[3],step[4])}</p></div><div class="actions"><button class="small ghost" data-action="end-guide">${t('退出','Exit')}</button><button class="small primary" data-action="next">${state.guide===tour.length-1?t('完成','Finish'):t('下一步 →','Next →')}</button></div></div>`}
function render(){document.documentElement.lang=state.lang==='zh'?'zh-CN':'en';const view=views.find(x=>x[0]===state.view)||views[0];$('#app').innerHTML=`<div class="shell ${state.wide?'wide-screen':''}"><aside class="sidebar"><div class="brand">HERSTAR<i>·</i></div><div class="brand-sub">恒升制造 · 运营演示</div><div class="nav-label">${t('经营驾驶舱','OPERATIONS WORKSPACE')}</div><nav class="nav" aria-label="${t('主要导航','Main navigation')}">${views.map(([key,icon,zh,en])=>`<button data-nav="${key}" class="${key===state.view?'active':''}" ${key===state.view?'aria-current="page"':''}><span class="icon">${icon}</span>${t(zh,en)}</button>`).join('')}</nav><div class="side-foot"><i class="dot"></i>${t('交互演示环境','INTERACTIVE DEMO')}<p>${t('真实企业背景<br>模拟运营数据<br>透明收益测算','Real company context<br>Dummy operating data<br>Transparent benefit estimates')}</p><a href="../portal.html">${t('采购与销售演示 ↗','Procurement & sales demo ↗')}</a></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">HERSTAR &nbsp;/&nbsp; <strong>${t(view[2],view[3])}</strong></div><div class="toolbar"><span class="top-tag">${t('演示模式 · 运营数据全部模拟','DEMO MODE · ALL OPERATIONAL DATA IS DUMMY')}</span><button class="small ghost" data-action="lang" aria-label="${t('Switch to English','切换中文')}">${state.lang==='zh'?'EN':'中文'}</button><button class="small" data-action="fullscreen">⛶ ${t('大屏','Present')}</button></div></header><div class="content">${({assistant:assistantView,wall:wallView,reports:reportView,systems:()=>systemsView(opsContext()),overview,orders,warehouse,engineering,telemetry,amoeba,scenarios:scenarioLab,sources}[state.view]||overview)()}<footer class="page-footer"><span>HERSTAR · ${t('恒升智造经营驾驶舱','Factory Intelligence')} / ${t('交互概念演示','Interactive concept demo')}</span><span>${t('未连接生产系统 · 估算不等于实际收益','No production connections · estimates are not realized savings')}</span></footer></div></main></div>${guide()}`;}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function showCentre(id){const a=centres.find(x=>x.id===id),m=c();const output=Math.min(500,Math.floor(state.tick/(state.p.cycle||2))),power=18+4*Math.sin(state.tick/7);$('#detail').innerHTML=`<div class="photo-card"><img src="${img(a.image)}" alt="${t(a.zh,a.en)}"><div class="photo-caption">${t('企业影片画面 · 本地资料来源；非实时监控','Corporate-film frame · local source; not a live camera')}</div></div><div class="dialog-content"><button class="dialog-close small" data-action="close">✕ ${t('关闭','Close')}</button><div class="eyebrow">${a.code} / ${t('虚构设备编号','FICTIONAL MACHINE ID')}</div><h1>${t(a.zh,a.en)}</h1>${badge()}<p>${t('演示 OPC UA / MTConnect → 边缘网关 → 数据模型 → Hermes 的信号路径。','Illustrates the signal path: OPC UA / MTConnect → edge gateway → data model → Hermes.')}</p><div class="telemetry-grid"><div><span>${t('模拟功率 · 时钟采样','Dummy power · clock sample')}</span><b>${n(power,1)} kW</b></div><div><span>${t('模拟计件 · 自播放开始','Dummy count · since play')}</span><b>${output}</b></div><div><span>${t('当前情景净收益预测','Current scenario benefit estimate')}</span><b>${money(m.net)}</b></div></div>${sparkline()}<p class="footnote">${t('信号是确定性的演示函数；图为固定虚构历史样本。此处为打开时的快照，不是真实设备监测。','Signals are deterministic demo functions; the chart is a fixed fictional history sample. Values are a snapshot at opening, not live equipment monitoring.')}</p><div class="callout">DEMO-HS-260908 · ${t('点击订单查看工序、物料和交付影响。','Inspect the order for operations, material and delivery impact.')}</div><button class="primary wide" data-action="centre-order">${t('查看关联订单 →','View linked order →')}</button></div>`;$('#detail').showModal()}
function exportPayload(){const m=c();return {title:'HERSTAR factory intelligence — DEMO / 模拟数据',provenance:'Company-source context with fictional operational data. Estimates are conditional, not realized savings.',scenario:state.scenario,appliedToSimulation:state.applied,simulationMinute:state.tick,period:'one modelled order',currency:'CNY',order:{id:'DEMO-HS-260908',customer:'Example Office (fictional)',product:'Dual-motor desk frame',quantity:500},assumptions:{...state.p},results:m,sourceFacts,limits:['No live system or LLM（大语言模型）connections','No financial or manufacturing execution','Released time and capacity excluded from cash benefit','One active scenario only','Finance must approve accounting definitions']}}
function download(content,type,name){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportBrief(){const data=exportPayload(),m=c();download(`<!doctype html><html lang="${state.lang==='zh'?'zh-CN':'en'}"><meta charset="utf-8"><title>HERSTAR — DEMO decision brief</title><style>body{font:15px/1.7 system-ui,sans-serif;max-width:850px;margin:40px auto;padding:25px;color:#28343e}h1{font-size:30px}strong{color:#365f82}table{width:100%;border-collapse:collapse}td,th{border-bottom:1px solid #ddd;padding:9px;text-align:left}.notice{background:#fff0ce;padding:16px}.big{font-size:36px}small{color:#666}@media print{body{margin:0}}</style><h1>HERSTAR · ${t('经营决策简报','Operations decision brief')}</h1><p class="notice">${t('演示报告 · 所有运营数据为模拟数据。测算不是实际收益，不是已批准的生产指令。','DEMO REPORT · All operating data is fictional. Estimates are not realized savings or approved production instructions.')}</p><h2>${esc(scenarioName())}</h2><p>DEMO-HS-260908 · 500 ${t('套双电机桌架','dual-motor desk frames')} · ${t('单订单 / 人民币','Per order / CNY')}</p><p class="big">${money(m.net)}</p><p>${t('预测净可避免成本 = 毛节省 − 执行成本','Projected net avoidable cost = gross saving − intervention cost')}</p><table><tr><td>${t('毛节省','Gross saving')}</td><td>${money(m.gross)}</td></tr><tr><td>${t('执行成本','Intervention cost')}</td><td>${money(m.intervention)}</td></tr><tr><td>${t('首年净收益（条件情景）','Year-one net benefit (conditional)')}</td><td>${money(m.yearOne)}</td></tr><tr><td>${t('静态回收期','Simple payback')}</td><td>${m.payback===null?t('无正收益，无法回收','No positive benefit'):n(m.payback,1)+' '+t('月','months')}</td></tr></table><h2>${t('复核与下一步','Review and next actions')}</h2><p>${t('生产负责人验证路线、质量负责人确认批次处理、财务负责人验证成本与重复频次。此文件为草稿，由人工审批后在真实系统执行。','Production validates the routing, quality approves lot disposition, and finance checks cost and recurrence assumptions. This is a draft for human review before any action in a real system.')}</p><h2>${t('所有可编辑假设 · 模拟数据','All editable assumptions · DUMMY DATA')}</h2><table>${Object.entries(state.p).map(([key,value])=>`<tr><td>${esc(t(...controlNames[key]))}</td><td>${n(value,Number.isInteger(value)?0:2)}</td></tr>`).join('')}</table><h2>${t('计算方法与边界','Method and boundaries')}</h2><p>${t('材料：(成品量/原利用率 − 成品量/目标利用率) × (采购价 − 回收价)。能源：(原用量 − 目标用量) × 电价。交付：停机 × 恢复比例 / 60 × 可避免加班费率。质量：(原返工件数 − 目标件数) × 增量返工成本。只使用所选案例的组成项并扣除执行费。','Material: (good output / baseline yield − good output / target yield) × (purchase price − recovery price). Energy: (baseline − target kWh) × tariff. Delivery: downtime × recovery fraction / 60 × avoidable overtime rate. Quality: (baseline − target rework units) × incremental rework cost. Only selected-scenario components are counted, less intervention cost.')}</p><p>${t('年度 = 净节省 × 可重复订单数；首年扣除一次性投入。回收月数 = 一次性投入 / (年度节省 / 12)。不计税费与贴现。人员时间、产能与订单收入不叠加进现金节省。','Annual = net saving × comparable orders; year one deducts setup investment. Payback months = setup / (annual saving / 12). Tax and discounting excluded. Staff time, capacity and order revenue are excluded from cash savings.')}</p><h2>${t('企业背景与来源','Company context and sources')}</h2>${sourceFacts.map(f=>`<p>${esc(t(f.zh,f.en))} — ${esc(f.status)}${f.source?`<br><small>${esc(f.source)}</small>`:''}</p>`).join('')}<p><small>${esc(data.provenance)}</small></p></html>`,'text/html;charset=utf-8',`Herstar-DEMO-${state.scenario}-brief.html`);toast(t('已导出带假设和来源的演示简报','Exported demo brief with assumptions and sources'))}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-nav],[data-action],[data-scenario],[data-ask],[data-centre],[data-bin],[data-unit]');if(!el)return;if(el.dataset.nav){nav(el.dataset.nav);return}if(el.dataset.scenario){state.scenario=el.dataset.scenario;state.applied=false;state.answer=null;render();return}if(el.dataset.ask){state.answer=el.dataset.ask;render();return}if(el.dataset.centre){showCentre(el.dataset.centre);return}if(el.dataset.bin!==undefined){state.bin=Number(el.dataset.bin);render();return}if(el.dataset.unit!==undefined){state.unit=Number(el.dataset.unit);render();return}switch(el.dataset.action){case'lang':state.lang=state.lang==='zh'?'en':'zh';render();break;case'play':state.playing=!state.playing;render();break;case'reset':state.p={...defaults};state.applied=false;state.tick=0;state.playing=false;state.answer=null;render();toast(t('当前情景已重置','Current scenario reset'));break;case'apply':state.applied=true;render();toast(t('仅已应用到模拟；未向真实系统发送任何操作','Applied to simulation only; no real system action'));break;case'explode':state.exploded=!state.exploded;render();break;case'guide':state.guide=0;nav('overview');break;case'next':state.guide++;if(state.guide>=tour.length){state.guide=-1;render();toast(t('导览完成，可导出简报','Tour complete. Export your brief.'))}else nav(tour[state.guide][0]);break;case'end-guide':state.guide=-1;render();break;case'close':$('#detail').close();break;case'centre-order':$('#detail').close();nav('orders');break;case'export':exportBrief();break;case'json':download(JSON.stringify(exportPayload(),null,2),'application/json','Herstar-DEMO-scenario.json');toast(t('已导出模拟数据 JSON','Exported dummy scenario JSON'));break;case'fullscreen':state.wide=!state.wide;render();try{if(state.wide&&!document.fullscreenElement)await document.documentElement.requestFullscreen();else if(!state.wide&&document.fullscreenElement)await document.exitFullscreen()}catch{toast(t('已切换宽屏布局；浏览器不支持全屏','Wide layout enabled; browser fullscreen unavailable'))}break}});
document.addEventListener('keydown',e=>{const el=e.target.closest('[data-centre]');if(el&&(e.key==='Enter'||e.key===' ')){e.preventDefault();showCentre(el.dataset.centre)}});
document.addEventListener('input',e=>{const key=e.target.dataset.param;if(!key)return;state.p[key]=Number(e.target.value);state.applied=false;const step=limits[key][2];$(`#out-${key}`).textContent=n(state.p[key],step<1?1:0);if($('#comparison'))$('#comparison').innerHTML=compareResult();if($('#time-result'))$('#time-result').innerHTML=timeResult();const aside=$('.impact-sticky');if(aside)aside.innerHTML=impact()+agent()});
document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement&&state.wide){state.wide=false;render()}});
setInterval(()=>{if(!state.playing)return;state.tick++;if($('#clock'))$('#clock').textContent=clock();if($('#live-signals'))$('#live-signals').innerHTML=signalCards();if($('#live-trace'))$('#live-trace').innerHTML=liveTrace()},1000);
window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(views.some(x=>x[0]===view)){state.view=view;render()}});
views.splice(4,0,['telemetry','⌁','设备数据采集','Equipment signals']);
function signalCards(){return centres.map((a,i)=>{const isFocus=state.scenario==='delivery'&&a.id==='weld';const duration=state.applied?c().lateTarget:state.p.downtime;const stopped=isFocus&&state.tick>=3&&state.tick<3+duration;const power=stopped?1.2:18+i*2+4*Math.sin((state.tick+i)/7);return `<div class="signal-card"><div class="signal-title"><span>${t(a.zh,a.en)}</span><span class="badge ${stopped?'dummy':''}">${stopped?t('停机模拟','SIM STOP'):t('运行模拟','SIM RUN')}</span></div><div class="signal-number">${n(power,1)} <small>kW</small></div><div class="signal-meta">${a.code} · ${t('模拟采样','SIM SAMPLE')} ${String(state.tick).padStart(4,'0')}</div><div class="progress-track"><i style="width:${Math.min(100,power/40*100)}%;${stopped?'background:var(--amber)':''}"></i></div></div>`}).join('')}
function liveTrace(){const pts=Array.from({length:61},(_,i)=>`${i*10},${90-35*Math.sin((state.tick-60+i)/7)-12*Math.sin((state.tick-60+i)/2)}`).join(' ');return `<svg viewBox="0 0 600 180" class="live-trace" role="img" aria-label="${t('随模拟时钟变化的功率示意曲线','Illustrative power curve driven by the simulation clock')}"><path d="M0 30H600M0 90H600M0 150H600" stroke="#ffffff10"/><polyline points="${pts}" fill="none" stroke="#a6e8bd" stroke-width="2.5"/></svg><div class="chart-labels"><span>${t('虚构参考波形 · 非设备实测','DUMMY REFERENCE WAVE · NOT MEASURED')}</span><span>${clock()}</span></div>`}
function telemetry(){return head('EDGE DATA / SIGNALS',t('设备状态与数据采集','Equipment status and data collection'),t('播放模拟时钟，观察采样变化。选择交付情景，焊接站在第 3 分钟进入模拟停机。','Play the simulation to watch samples change. In the delivery scenario, welding enters a simulated stop at minute 3.'))+strip()+`<div class="grid-main"><div class="stack">${panel(t('七个中心 · 模拟功率采样','Seven centres · dummy power samples'),`<div id="live-signals" class="signal-grid">${signalCards()}</div>`,badge())}${panel(t('数据采集示意','Data collection illustration'),`<div class="panel-body"><div id="live-trace">${liveTrace()}</div><div class="system-flow"><div>OPC UA / MTConnect<small>${t('虚构信号','Synthetic signals')}</small></div><span>→</span><div>${t('边缘网关','Edge gateway')}</div><span>→</span><div>MCP / Hermes</div></div><div class="callout">${t('瞬时功率卡是演示函数，不对其积分推导订单能耗。订单节能测算使用实验室中明确输入的 kWh 假设。参考曲线为独立合成波形。','Power cards are demonstration functions, not integrated into order energy use. Order energy savings use explicit kWh assumptions in the lab. The reference curve is a separate synthetic waveform.')}</div></div>`,badge())}</div>${right()}</div>`}
if(views.some(v=>v[0]===location.hash.slice(1)))state.view=location.hash.slice(1);
mountReports(opsContext,render,toast);
render();
mountChat(opsContext,nav);
new MutationObserver(()=>annotateSystems($('#detail'))).observe($('#detail'),{childList:true});

function opsContext(){return {p:{...state.p},scenario:state.scenario,applied:state.applied,lang:state.lang,tick:state.tick,view:state.view};}
function assistantView(){return `<div class="page-head"><div><div class="eyebrow">HERSTAR / INTERNAL OPERATIONS AGENT</div><h1>${t('用一个问题，查清跨系统的原因。','One question. Evidence across systems.')}</h1></div></div><div class="agent-page"></div>`;}

function wallView(){const s=snapshot(opsContext()),m=s.metrics;return head('FACTORY WALL / SIMULATED',t('生产运行大屏','Production display'),t('当前订单、库存风险与七个中心的模拟采集信号。点击大屏可切换展示模式。','Current order, stock risks and synthetic equipment signals.'))+strip()+`<div class="ops-wall"><div class="stats">${stat('关联订单',m.orderQty,'套','DEMO-HS-260908 · 虚构')}${stat('可用钢材',n(m.availableKg),'kg','不含隔离库存')}${stat('需求缺口',n(m.shortfallKg,1),'kg','依当前情景计算','warning')}${stat('预计延迟',n(m.delayMinutes),'分钟','情景假设，非实际预测','warning')}</div>${panel('七大制造中心 · 模拟采样',`<div id="live-signals" class="signal-grid">${signalCards()}</div>`,badge())}<div class="grid-two">${panel('功率参考波形',`<div class="panel-body"><div id="live-trace">${liveTrace()}</div></div>`,badge())}${panel('管理提醒',`<div class="panel-body"><div class="callout">600 kg 保持隔离，不自动计入可用库存。</div><div class="callout">订单 Rev B 与隔离批次 Rev A 不一致，需要工程与质量复核。</div><button data-nav="assistant" class="primary">让经营助手解释原因 →</button></div>`,badge())}</div></div>`;}
